{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE spfclaims_final_new_spf_table_c AS WITH base AS ( SELECT *, CASE WHEN UPPER(TRIM(channel_name)) IN (\'SHOPIFY\', \'B2C-DELHIVERY\', \'B2C-PROZO\', \'B2C-EKART\', \'B2C PROZO\', \'B2C-BLUEDART\', \'B2C-BLITZ\') THEN \'SHOPIFY\' WHEN UPPER(TRIM(channel_name)) IN (\'SAPL_AJIO_OMNI_2\', \'SAPL_AJIO_OMNI_EMIZA\', \'SAPL_AJIO_OMNI\', \'AJIO\', \'MP_AJIO\') THEN \'AJIO\' WHEN UPPER(TRIM(channel_name)) IN (\'FLIPKART_SAPLWH2\', \'FLIPKART_SAPL\', \'FLIPKART\', \'MP-FLIPKART\', \'FLIPKART_SAPL_EMIZA\') THEN \'FLIPKART\' WHEN UPPER(TRIM(channel_name)) IN (\'MYNTRAPMP_SAPL-WH2\', \'SAPL_MYNTAPPMP\', \'SAPL_MYNTRAPPMP\', \'MP-MYNTRA\', \'SAPL_MYNTAPP_EMIZA\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA_EMIZA\', \'Myntra\', \'MYNTRA\') THEN \'MYNTRA\' WHEN UPPER(TRIM(channel_name)) IN (\'AMAZON_FLEX_WH2\', \'AMAZON_FLEX_API_SAPL\', \'MP-AMAZON\', \'AMAZON\') THEN \'AMAZON\' WHEN UPPER(TRIM(channel_name)) IN (\'MP-NYKAA\', \'NYKAA_FASHION_WH2\', \'NYKAA_FASHION_WH\', \'NYKAA_COM_SAPLWH\',\'NYKAA_COM_WH2\', \'NYKAA\') THEN \'NYKAA\' WHEN UPPER(TRIM(channel_name)) = \'MP-CRED\' THEN \'CRED\' WHEN UPPER(TRIM(channel_name)) = \'GROO SHIP\' THEN \'GROO SHIP\' WHEN UPPER(TRIM(channel_name)) = \'DONOSHOP\' THEN \'DONOSHOP\' WHEN UPPER(TRIM(channel_name)) = \'BLUEDART\' THEN \'BLUEDART\' WHEN UPPER(TRIM(channel_name)) = \'SELFSHIP\' THEN \'SELFSHIP\' ELSE UPPER(TRIM(channel_name)) END AS cleaned_channel_name FROM spfclaims_master_spf_table WHERE received_date NOT IN (\'\', \'null\') ), cleaned AS ( SELECT CASE WHEN TRIM(CAST(ID AS TEXT)) IN (\'\', \'null\') THEN NULL ELSE ID END AS ID, TRY_TO_DATE(NULLIF(NULLIF(month, \'\'), \'null\'), \'DD-MM-YYYY\') AS month, TRY_TO_NUMBER(NULLIF(NULLIF(AGEING, \'\'), \'null\')) AS AGEING, NULLIF(NULLIF( CASE WHEN UPPER(TRIM(DONE_BY)) IN (\'PRADEEP\',\'P\') THEN \'PRADEEP\' WHEN UPPER(TRIM(DONE_BY)) IN (\'BAJARANGI\',\'B\') THEN \'BAJARANGI\' WHEN UPPER(TRIM(DONE_BY)) IN (\'RAMYA\',\'R\') THEN \'RAMYA\' WHEN UPPER(REPLACE(TRIM(DONE_BY),\'’\',\'\')) IN (\'CHANDAN\',\'C\') THEN \'CHANDAN\' WHEN UPPER(REPLACE(TRIM(DONE_BY),\'✓\',\'\')) IN (\'DHYAN\',\'D\') THEN \'DHYAN\' ELSE TRIM(DONE_BY) END, \'\'), \'null\') AS DONE_BY, NULLIF(NULLIF(REMARKS, \'\'), \'null\') AS REMARKS, NULLIF(NULLIF(WH_TYPE, \'\'), \'null\') AS WH_TYPE, CASE WHEN TRIM(CAST(TOTAL_QTY AS TEXT)) IN (\'\', \'null\') THEN NULL ELSE TOTAL_QTY END AS TOTAL_QTY, NULLIF(NULLIF(CREATED_BY, \'\'), \'null\') AS CREATED_BY, NULLIF(NULLIF(qc_comment, \'\'), \'null\') AS qc_comment, CASE WHEN qc_comment IS NULL OR LOWER(TRIM(qc_comment)) IN (\'\', \'null\') THEN NULL WHEN LOWER(qc_comment) LIKE \'%washing%\' OR LOWER(qc_comment) LIKE \'%wash%\' THEN \'Good Inventory\' WHEN LOWER(qc_comment) LIKE \'%fake%\' OR LOWER(qc_comment) LIKE \'%faqke%\' OR LOWER(qc_comment) LIKE \'%faker%\' OR LOWER(qc_comment) LIKE \'%fakr%\' OR LOWER(qc_comment) LIKE \'%fakle%\' OR LOWER(qc_comment) LIKE \'%faake%\' OR LOWER(qc_comment) LIKE \'%fa ke%\' OR LOWER(qc_comment) LIKE \'%fakw%\' OR LOWER(qc_comment) LIKE \'%fvakr%\' OR LOWER(qc_comment) LIKE \'%fske%\' OR LOWER(qc_comment) LIKE \'%ffake%\' OR LOWER(qc_comment) LIKE \'%fak e%\' OR LOWER(qc_comment) LIKE \'%fa ke product%\' OR LOWER(qc_comment) LIKE \'%fak e product%\' OR LOWER(qc_comment) LIKE \'%faje%\' OR LOWER(qc_comment) LIKE \'%rfake%\' OR LOWER(qc_comment) LIKE \'%Other Brand%\' OR LOWER(qc_comment) LIKE \'%FALKE%\' OR LOWER(qc_comment) LIKE \'%rake%\' OR LOWER(qc_comment) LIKE \'%fae%\' OR LOWER(qc_comment) LIKE \'%fakje%\' OR LOWER(qc_comment) LIKE \'%fdake%\' OR LOWER(qc_comment) LIKE \'%FAK%\' OR LOWER(qc_comment) LIKE \'%falke%\' OR LOWER(qc_comment) LIKE \'%fack%\' OR LOWER(qc_comment) LIKE \'%Other Brand%\' OR LOWER(qc_comment) LIKE \'%Other Brand - FAK%\' OR LOWER(qc_comment) LIKE \'%Other Brand%\' THEN \'Fake\' WHEN LOWER(qc_comment) LIKE \'%wpr%\' OR LOWER(qc_comment) LIKE \'%wrp%\' OR LOWER(qc_comment) LIKE \'%wpt%\' OR LOWER(qc_comment) LIKE \'%wprf%\'OR LOWER(qc_comment) LIKE \'%fpr%\' OR LOWER(qc_comment) LIKE \'%wp[r%\' OR LOWER(qc_comment) LIKE \'%Wrong Product - W[PR%\' OR LOWER(qc_comment) LIKE \'%Wrong Product%\' OR LOWER(qc_comment) LIKE \'%wpe%\' OR LOWER(qc_comment) LIKE \'%wor%\' OR LOWER(qc_comment) LIKE \'%wrong%\' OR LOWER(qc_comment) LIKE \'%wpor%\' OR LOWER(qc_comment) LIKE \'%wr%\' THEN \'WPR\' WHEN LOWER(qc_comment) LIKE \'%damage%\' OR LOWER(qc_comment) LIKE \'%damaged%\' OR LOWER(qc_comment) LIKE \'%damaga%\' OR LOWER(qc_comment) LIKE \'%damgaed%\' OR LOWER(qc_comment) LIKE \'%damaage%\' OR LOWER(qc_comment) LIKE \'%damgaged%\' OR LOWER(qc_comment) LIKE \'%damag%\' OR LOWER(qc_comment) LIKE \'%damaded%\' OR LOWER(qc_comment) LIKE \'%dama%\' OR LOWER(qc_comment) LIKE \'%damged%\' OR LOWER(qc_comment) LIKE \'%button damage%\' OR LOWER(qc_comment) LIKE \'%coller shade damage%\' OR LOWER(qc_comment) LIKE \'%da,mage%\' THEN \'Damage\' WHEN LOWER(qc_comment) LIKE \'%missing%\' OR LOWER(qc_comment) LIKE \'%empty box%\' OR LOWER(qc_comment) LIKE \'%empty shipment%\' OR LOWER(qc_comment) LIKE \'%empty product%\' OR LOWER(qc_comment) LIKE \'%empty%\' THEN \'Missing\' WHEN LOWER(qc_comment) LIKE \'%partial%\' OR LOWER(qc_comment) LIKE \'%parsal%\' OR LOWER(qc_comment) LIKE \'%parcial%\' OR LOWER(qc_comment) LIKE \'%partail%\' OR LOWER(qc_comment) LIKE \'%partila%\' OR LOWER(qc_comment) LIKE \'%partal%\' OR LOWER(qc_comment) LIKE \'%partiol%\' OR LOWER(qc_comment) LIKE \'%partial shipment%\' OR LOWER(qc_comment) LIKE \'%partial returns%\' OR LOWER(qc_comment) LIKE \'%partial return%\' OR LOWER(qc_comment) LIKE \'%partial rerurns%\' OR LOWER(qc_comment) LIKE \'%partail returns%\' OR LOWER(qc_comment) LIKE \'%partila returns%\' OR LOWER(qc_comment) LIKE \'%partial; returns%\' OR LOWER(qc_comment) LIKE \'%partial shipmant%\' OR LOWER(qc_comment) LIKE \'%partal shipment%\' OR LOWER(qc_comment) LIKE \'%parsial shipment%\' OR LOWER(qc_comment) LIKE \'%Incomplete Product%\' OR LOWER(qc_comment) LIKE \'%parsial%\' OR LOWER(qc_comment) LIKE \'%artial%\' OR LOWER(qc_comment) LIKE \'%Incomplete Product - partlal returns%\' OR LOWER(qc_comment) LIKE \'%Incomplete Product - incomplete product%\' THEN \'Partial Returns\' ELSE NULL END AS qc_bucket, cleaned_channel_name AS channel_name, UPPER(NULLIF(NULLIF(tracking_no, \'\'), \'null\')) AS tracking_no, NULLIF(NULLIF(item_skucode, \'\'), \'null\') AS item_skucode, NULLIF(NULLIF(PHY_SKU_CODE, \'\'), \'null\') AS PHY_SKU_CODE, NULLIF(NULLIF(PUTAWAY_CODE, \'\'), \'null\') AS PUTAWAY_CODE, TRY_TO_DATE(NULLIF(NULLIF(QC_DONE_DATE, \'\'), \'null\'), \'DD-MM-YYYY\') AS QC_DONE_DATE, NULLIF(NULLIF(QC_VIDEO_LINK, \'\'), \'null\') AS QC_VIDEO_LINK, TRY_TO_DATE(NULLIF(NULLIF(received_date, \'\'), \'null\'), \'DD-MM-YYYY\') AS received_date, NULLIF(NULLIF(shipment_type, \'\'), \'null\') AS shipment_type, NULLIF(NULLIF(ticket_number, \'\'), \'null\') AS ticket_number, COALESCE( TRY_TO_DATE(NULLIF(NULLIF(ticket_raised_date, \'\'), \'null\'), \'DD-MM-YYYY\'), CAST(TRY_TO_TIMESTAMP(NULLIF(NULLIF(ticket_raised_date, \'\'), \'null\'), \'MON DD, YYYY HH12:MI AM\') AS DATE) ) AS ticket_raised_date, NULLIF(NULLIF(ticket_status, \'\'), \'null\') AS ticket_status, LOWER( TRIM( REGEXP_REPLACE( REPLACE(ticket_status, CHR(160), \' \'), \'\\s+\', \' \' ) ) ) AS cleaned_status, NULLIF(NULLIF(SALE_ORDER_CODE, \'\'), \'null\') AS SALE_ORDER_CODE, NULLIF(NULLIF(REJECTION_REASON, \'\'), \'null\') AS REJECTION_REASON, NULLIF(NULLIF(TICKET_RAISED_BY, \'\'), \'null\') AS TICKET_RAISED_BY, CASE WHEN TRIM(CAST(LAST_UPDATED_AT AS TEXT)) IN (\'\', \'null\') THEN NULL ELSE LAST_UPDATED_AT END AS LAST_UPDATED_AT, TO_TIMESTAMP(CAST(FLOOR(LAST_UPDATED_AT / 1000) AS NUMBER)) AS last_updated_at_readable, NULLIF(NULLIF(CONCAT_WS(\'_\', tracking_no, item_skucode), \'\'), \'null\') AS CONCATE1, CASE WHEN LOWER(remarks) = \'not eligible\' THEN \'Not Eligible\' WHEN LOWER(remarks) = \'emiza shipment\' THEN \'Not Eligible\' WHEN LOWER(created_by) IN (\'emiza1@snich.club\', \'emiza2@snitch.club\') THEN \'Not Eligible\' WHEN ( LOWER(cleaned_channel_name) = \'flipkart\' AND ( LOWER(qc_comment) LIKE \'%wpr%\' OR LOWER(qc_comment) LIKE \'%damage%\' OR LOWER(qc_comment) LIKE \'%damaged%\' OR LOWER(qc_comment) LIKE \'%dama%\' OR LOWER(qc_comment) LIKE \'%missing%\' OR LOWER(qc_comment) LIKE \'%wrong product%\' ) AND LOWER(qc_comment) NOT LIKE \'%partial%\' ) THEN \'Not Eligible\' WHEN ( LOWER(cleaned_channel_name) = \'shopify\' AND LOWER(qc_comment) LIKE \'%fake%\' ) THEN \'Eligible\' WHEN LOWER(cleaned_channel_name) = \'shopify\' THEN \'Not Eligible\' ELSE \'Eligible\' END AS eligible_to_raise_flag FROM base ), latest_status AS ( SELECT * FROM cleaned QUALIFY ROW_NUMBER() OVER ( PARTITION BY tracking_no, item_skucode ORDER BY last_updated_at DESC ) = 1 ) SELECT *, CASE WHEN lower(REMARKS) = \'raised\' THEN 1 WHEN ticket_number IS NOT NULL AND ticket_number != \'Not Eligible\' THEN 1 WHEN ticket_raised_date IS NOT NULL THEN 1 WHEN LOWER(TRIM(ticket_status)) IN ( \'claim accepted\', \'claim denied\', \'pending\', \'accept\', \'approved\', \'dispute accepted\', \'claim accepted\', \'payment completed\', \'claim denied\', \'reject\',\'rejected\',\'dispute not accepted\', \'not approved\', \'raised within tat\', \'under investigation\', \'open\', \'awaiting seller response\' ) THEN 1 ELSE 0 END AS ticket_raised_flag, CASE WHEN LOWER(cleaned_status) IN (\'accept\',\'accepted\', \'approved\',\'approval\', \'dispute accepted\', \'claim accepted\', \'payment completed\',\'payment_completed\') THEN \'Approved\' WHEN LOWER(cleaned_status) IN (\'claim denied\', \'reject\',\'rejected\', \'dispute not accepted\', \'not approved\',\'already tat breached\',\'closed-no response\') THEN \'Rejected\' WHEN LOWER(cleaned_status) IN (\'raised within tat\',\'raised\',\'under investigation\', \'open\', \'awaiting seller response\',\'awaiting_agent_response\',\'pending from snitch team\') THEN \'Under Investigation\' WHEN LOWER(cleaned_status) IN (\'to be raised\', \'nf\', \'o\', \'#na\', \'#n/a\', \'pending\', \'0\',\'not available\') THEN \'Pending\' ELSE \'Unknown\' END AS ticket_status_bucket FROM latest_status;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
